import { exec } from "node:child_process";

export function isExeRunning(exeName: string): Promise<boolean> {
  return new Promise((resolve, reject) => {
    exec(`chcp 65001 && tasklist /FO CSV /NH /FI "IMAGENAME eq ${exeName}"`, (err, stdout, stderr) => {
      if (err || stderr) {
        return reject(err || stderr);
      }

      const isRunning = stdout.includes(exeName);
      return resolve(isRunning);
    });
  });
}

export function killEXE(exeName: string): Promise<boolean> {
  return new Promise((resolve, reject) => {
    exec(`chcp 65001 && taskkill /IM "${exeName}" /F /T`, (err, _stdout, stderr) => {
      if (err || stderr) {
        return reject(err || stderr);
      }

      return resolve(true);
    });
  });
}
